// Embedding network policy: set on the serialized application owner thread.
static thread_local bool g_rtrStreamlineSessionEnabled = true;
bool RtrSetStreamlineSessionEnabled(bool enabled)
{
    const bool previous = g_rtrStreamlineSessionEnabled;
    g_rtrStreamlineSessionEnabled = enabled;
    return previous;
}

bool RtrStreamlineSessionEnabled()
{
    return g_rtrStreamlineSessionEnabled;
}

if (!g_rtrStreamlineSessionEnabled)
{
    if (m_slInitialized)
        return false;
    m_dlssAvailable = m_nisAvailable = m_deepdvcAvailable = false;
    m_dlssgAvailable = m_dlssrrAvailable = m_reflexAvailable = m_pclAvailable = false;
    m_currentFrame = nullptr;
    m_device = nullptr;
    log::info("Streamline is not required by this session; initialization is skipped.");
    return true;
}
